INSERT INTO `sop` VALUES
(58,'Monthly Online VAT Submission ( Sohub )','To define the standardized process for accurate and timely online submission of Value Added Tax (VAT) returns in compliance with applicable tax laws and regulations.','<h2>Instructions & Execution Stages</h2><ul data-spread=\"false\"><li><p>Confirm VAT registration and filing deadline</p></li><li><p>Collect sales and purchase invoices</p></li><li><p>Verify invoice accuracy and VAT classification</p></li><li><p>Calculate output VAT and input VAT</p></li><li><p>Reconcile VAT with accounting records</p></li><li><p>Prepare draft VAT return</p></li><li><p>Review and obtain internal approval</p></li><li><p>Log in to VAT portal and enter data</p></li><li><p>Submit VAT return online</p></li><li><p>Generate and save acknowledgment</p></li><li><p>Make VAT payment (if applicable)</p></li><li><p>File records and monitor complianc</p></li></ul>',1,1,1,'3','5',10,'2026-01-12 21:31:46','2026-01-12 21:31:46','{\"title\":\"Verify invoice accuracy and VAT classification\",\"labels\":[\"Calculate output VAT and input VAT\",\"Submit VAT return online\",\"File records and monitor compliance\"]}','{\"title\":\"Check the File records and monitor compliance\",\"labels\":[]}',NULL,'graph TD\nA[\"Start: Verify invoice accuracy and VAT classification\"]\nN1[\"Calculate output VAT and input VAT\"]\nA --> N1\nN2[\"Submit VAT return online\"]\nN1 --> N2\nN3[\"File records and monitor compliance\"]\nN2 --> N3\nN4[\"End\"]\nN3 --> N4','graph TD\nA[\"Start: Check the File records and monitor compliance\"]\nN1[\"End\"]\nA --> N1');
