INSERT INTO `tracker_issues` VALUES
(1,'SWD-1','SWD','Explore',NULL,'EMP System Usage & Compliance Audit','<h4 id=\"event-title\" style=\"font-family: Signika, sans-serif; color: rgb(77, 77, 77); background-color: rgb(236, 237, 240);\"><p style=\"font-size: 14px;\">Verify whether EMP is being used correctly, consistently, and according to defined SOPs.</p><p style=\"font-size: 14px;\">Audit Scope:</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>Task creation &amp; updates done inside EMP (not WhatsApp/verbal only)</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>Proper SOP selection for each task</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>Timely work summary submission</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>Correct use of To-Do, Observation, Milestone &amp; Approval flows</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>Evidence/proof attached where required</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>Verifier flow followed (no self-verification)</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>No bypassing of EMP for daily/weekly/monthly operations</p><p style=\"font-size: 14px;\">Audit Checklist:</p><p style=\"font-size: 14px;\">1.<span xss=\"removed\">&nbsp;</span>Tasks created inside EMP for all assigned responsibilities</p><p style=\"font-size: 14px;\">2.<span xss=\"removed\">&nbsp;</span>Correct SOP selected for each task</p><p style=\"font-size: 14px;\">3.<span xss=\"removed\">&nbsp;</span>Status updates done regularly (no stagnant tasks)</p><p style=\"font-size: 14px;\">4.<span xss=\"removed\">&nbsp;</span>Proof attached where SOP demands it</p><p style=\"font-size: 14px;\">5.<span xss=\"removed\">&nbsp;</span>Verifier action completed within verifier due time</p><p style=\"font-size: 14px;\">6.<span xss=\"removed\">&nbsp;</span>No external-only reporting (WhatsApp/Excel/email without EMP entry)</p><p style=\"font-size: 14px;\">7.<span xss=\"removed\">&nbsp;</span>Escalations triggered where deadlines were missed</p><p style=\"font-size: 14px;\">Outcome:</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>✅ Fully compliant</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>⚠️ Partially compliant (issues noted)</p><p style=\"font-size: 14px;\">•<span xss=\"removed\">&nbsp;</span>❌ Non-compliant (action required)</p><p style=\"font-size: 14px;\">Non-compliance may result in follow-up tasks, warning, or access restriction as per policy.</p></h4>','todo','Medium',58,58,'1','1','1','','2026-01-19 23:59:59',NULL,NULL,'1','approved','2026-01-19 19:22:43',58,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,58,'2026-01-19 19:22:43',0.0,0.0,0,NULL,NULL,0,0,0);
